using System;using System.IO;using System.Diagnostics;using System.Security.AccessControl;using System.Security.Principal;using System.Threading;using System.Runtime.InteropServices;
internal static class ModernIntegration {
 internal const string TaskName="ThinkPad Modes";
 internal static string OpenEvent{get{return @"Local\ThinkPadModes.Open."+WindowsIdentity.GetCurrent().User.Value;}}
 internal static EventWaitHandle CreateOpenEvent(){var security=new EventWaitHandleSecurity();security.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544",WindowsIdentity.GetCurrent().User.Value})security.AddAccessRule(new EventWaitHandleAccessRule(new SecurityIdentifier(sid),EventWaitHandleRights.FullControl,AccessControlType.Allow));bool created;return new EventWaitHandle(false,EventResetMode.AutoReset,OpenEvent,out created,security);}
 internal static bool RevealExisting(){try{using(var signal=EventWaitHandle.OpenExisting(OpenEvent,EventWaitHandleRights.Modify)){signal.Set();return true;}}catch(WaitHandleCannotBeOpenedException){return false;}catch(UnauthorizedAccessException){return false;}}
 internal static bool RunInstalled(string image){object service=null,folder=null,task=null;try{string protectedRoot=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),"ThinkPadModes")+Path.DirectorySeparatorChar;if(!Path.GetFullPath(image).StartsWith(protectedRoot,StringComparison.OrdinalIgnoreCase))return false;service=Activator.CreateInstance(Type.GetTypeFromProgID("Schedule.Service"));dynamic scheduler=service;scheduler.Connect();folder=scheduler.GetFolder("\\");dynamic f=folder;task=f.GetTask(TaskName);dynamic t=task;dynamic definition=t.Definition;if(!t.Enabled||definition.Principal.RunLevel!=1||definition.Actions.Count!=1)return false;string principal=definition.Principal.UserId;if(!String.Equals(principal,WindowsIdentity.GetCurrent().User.Value,StringComparison.OrdinalIgnoreCase))return false;dynamic action=definition.Actions.Item(1);if(!String.Equals(Path.GetFullPath((string)action.Path),Path.GetFullPath(image),StringComparison.OrdinalIgnoreCase)||(string)action.Arguments!="--startup")return false;t.Run(null);return true;}catch{return false;}finally{foreach(var o in new[]{task,folder,service})if(o!=null&&Marshal.IsComObject(o))Marshal.FinalReleaseComObject(o);}}
 internal static void Ready(string folder){string file=Path.Combine(ThinkPadManualApp.Root,"startup-status.json");ThinkPadModesV3.Atomic.Write(file,new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(new{UTC=DateTime.UtcNow.ToString("o"),Ready=true,Image=ThinkPadManualApp.Image,VersionSHA256=ThinkPadModesV3.Digest.Of(ThinkPadManualApp.Image),Pid=Process.GetCurrentProcess().Id,SessionFolder=folder,Startup=ThinkPadManualApp.StartupLaunch}));}
}
